#include <bits/stdc++.h>
using namespace std;

// Interactive skeleton for Zigzag Game (Alice as default, Increasing, start at 1).
// This is a greedy strategy: after the judge makes a move, we respond by selecting
// the best unvisited neighbor of the current node that satisfies the weight constraint
// (greater than last_w for Increasing, less than last_w for Decreasing).
// The program uses the matrix a[i][j] which denotes weight between node i+1 (left) and node j+n+1 (right).

static inline long long edge_weight(int u, int v, int n, const vector<vector<long long>>& a){
    // nodes are 1..n (left), n+1..2n (right)
    if(u <= n && v > n) return a[u-1][v-(n+1)];
    if(v <= n && u > n) return a[v-1][u-(n+1)];
    return -1; // not adjacent
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    if(!(cin >> t)) return 0;
    while(t--){
        int n; cin >> n;
        vector<vector<long long>> a(n, vector<long long>(n));
        for(int i=0;i<n;++i) for(int j=0;j<n;++j) cin >> a[i][j];

        int total = 2 * n;
        // Strategy: Alice as Increasing, start at node 1
        int my_type = 1; // 1 = Increasing, 0 = Decreasing
        int start = 1;

        cout << "A\n";
        cout << "I " << start << "\n";
        cout.flush();

        vector<char> visited(total+1, false);
        visited[start] = true;
        int current = -1;          // current position after judge's first move from start
        long long last_w = -1;       // weight of the last traversed edge

        // Read judge's first move from the starting node
        int judge_move;
        if(!(cin >> judge_move)) return 0;
        if(judge_move == -1) break;

        // The judge moved from 'start' to 'judge_move'
        current = judge_move;
        visited[current] = true;
        last_w = edge_weight(start, current, n, a);

        // Now it's our turn to move from 'current'
        while(true){
            // Find best next move from current to an unvisited vertex satisfying the constraint
            int best = -1;
            long long best_w = 0;
            for(int v = 1; v <= total; ++v){
                if(visited[v]) continue;
                long long w = edge_weight(current, v, n, a);
                if(w < 0) continue; // not adjacent
                bool ok = (my_type == 1) ? (w > last_w) : (w < last_w);
                if(!ok) continue;
                if(best == -1 || (my_type == 1 ? w > best_w : w < best_w)){
                    best = v; best_w = w;
                }
            }
            if(best == -1){
                cout << -1 << "\n";
                cout.flush();
                return 0;
            }
            // Make our move
            cout << best << "\n";
            cout.flush();
            visited[best] = true;
            // Update last_w and current for next turn
            last_w = best_w;
            int prev = current;
            current = best;

            // Read judge's response (their move from new current)
            int judge_resp;
            if(!(cin >> judge_resp)) return 0;
            if(judge_resp == -1) break;
            // Judge moved from 'current' to 'judge_resp'
            visited[judge_resp] = true;
            last_w = edge_weight(current, judge_resp, n, a);
            current = judge_resp;
        }
    }
    return 0;
}
