ry = [&](int u)->int {\n        int res = GLOBAL_NEG;\n        while(head[u] != head[0]){\n            res = max(res, seg.query(pos[ head[u] ], pos[u]));\n            u = parent[ head[u] ];\n        }\n        res = max(res, seg.query(pos[0], pos[u]));\n        return res;\n    };\n\n    // Process queries\n    for(int qi=0; qi<m; ++qi){\n        int type; cin >> type;\n        if(type == 1){\n            int i, x; cin >> i >> x;\n            int u = term[i]; int oldVal = val[i];\n            auto it = ms[u].find(oldVal); if(it != ms[u].end()) ms[u].erase(it);\n            ms[u].insert(x); val[i] = x;\n            int newVal = ms[u].empty() ? GLOBAL_NEG : *ms[u].rbegin();\n            if(newVal != nodeVal[u]){ nodeVal[u] = newVal; seg.update(pos[u], newVal); }\n        } else {\n            string qstr; cin >> qstr; int cur = 0; int ans = GLOBAL_NEG;\n            for(char ch : qstr){ int c = ch - 'a'; cur = trie[cur].nxt[c]; int v = pathQuery(cur); if(v > ans) ans = v; }\n            cout << (ans == GLOBAL_NEG ? -1 : ans) << \"\\n\";\n        }\n    }\n\n    return 0;\n}\nCPP\n",
