#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n_ = 0) { init(n_); }
    void init(int n_) {
        n = n_;
        bit.assign(n + 2, 0);
    }
    void add(int idx, long long val) {
        for (int i = idx; i <= n; i += i & -i) bit[i] += val;
    }
    void range_add(int L, int R, long long val) {
        // L, R are 0-based depths
        int l = L + 1;
        int r = R + 1;
        if (l > n) return;
        add(l, val);
        if (r + 1 <= n) add(r + 1, -val);
    }
    long long sumPrefix(int idx) {
        long long s = 0;
        for (int i = idx; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
    long long queryDepth(int depth) {
        return sumPrefix(depth + 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int x, y; cin >> x >> y;
        g[x].push_back(y);
        g[y].push_back(x);
    }
    int m; cin >> m;
    vector<vector<pair<int, long long>>> at(n + 1);
    for (int i = 0; i < m; ++i) {
        int v, d; long long x; cin >> v >> d >> x;
        at[v].push_back({d, x});
    }

    Fenwick bit(n); // depths range [0, n-1]
    vector<long long> ans(n + 1, 0);
    vector<int> depth(n + 1, 0);

    struct Item { int u; int p; int state; };
    vector<Item> st;
    st.reserve(2 * n);
    st.push_back({1, 0, 0});
    depth[1] = 0;

    while (!st.empty()) {
        auto cur = st.back(); st.pop_back();
        int u = cur.u, p = cur.p, state = cur.state;
        if (state == 0) {
            // entering u
            for (auto &qq : at[u]) {
                int d = qq.first; long long x = qq.second;
                int L = depth[u];
                long long Rd = (long long)depth[u] + d;
                int R = (Rd > (n - 1) ? (n - 1) : (int)Rd);
                if (L <= R) bit.range_add(L, R, x);
            }
            ans[u] = bit.queryDepth(depth[u]);
            // schedule exit
            st.push_back({u, p, 1});
            // push children
            for (int v : g[u]) {
                if (v == p) continue;
                depth[v] = depth[u] + 1;
                st.push_back({v, u, 0});
            }
        } else {
            // exiting u: revert its queries
            for (auto &qq : at[u]) {
                int d = qq.first; long long x = qq.second;
                int L = depth[u];
                long long Rd = (long long)depth[u] + d;
                int R = (Rd > (n - 1) ? (n - 1) : (int)Rd);
                if (L <= R) bit.range_add(L, R, -x);
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        cout << ans[i] << (i == n ? '\n' : ' ');
    }
    return 0;
}
